<script setup lang="ts">
import {ref,computed} from 'vue'
import AppShell from '../components/AppShell.vue'
import EmptyState from '../components/EmptyState.vue'
import StatusPill from '../components/StatusPill.vue'
import PointBalance from '../components/PointBalance.vue'
import LoadMore from '../components/LoadMore.vue'
import {usePage} from '../composables/usePage'
import {get,getAll,mutate,familyPath,childPath} from '../services/api'
import {go} from '../services/navigation'
import {label,dateTime,integer} from '../services/format'
import type {Reward,Availability,Account,Order,Wish,Child,PageResult} from '../services/types'
const props=defineProps<{page:string;query:Record<string,string>}>()
const isChildPage=['wishes','childReward','orders','childOrder'].includes(props.page)
const rewards=ref<Reward[]>([]),orders=ref<Order[]>([]),reward=ref<Reward|null>(null),order=ref<Order|null>(null),account=ref<Account|null>(null),availability=ref<Availability|null>(null),wish=ref<Wish|null>(null),children=ref<Child[]>([]),childId=ref(props.query.childId||''),tab=ref(props.query.tab||'catalog'),status=ref(''),category=ref(''),cursor=ref<string|null>(null),hasMore=ref(false),orderCursor=ref<string|null>(null),ordersMore=ref(false),confirmRequest=ref(false),action=ref(''),reason=ref(''),childReason=ref('CHANGED_MIND'),note=ref(''),delivered=ref(false),stockDelta=ref(''),stockReason=ref('')
const form=ref({name:'',description:'',category:'TIME',benefitDescription:'',timeMinutes:'20',artKey:'game',costPoints:'30',stockMode:'UNLIMITED',initialStock:'0',weeklyLimit:'',childIds:[] as string[]})
const categories=['TIME','FOOD','ITEM','EXPERIENCE'];const artKeys=['game','icecream','fries','gift','book','outing'];const artNames=['游戏','冰淇淋','薯条','礼物','图书','共同出游'];const childReasons=['我改变主意了','以后再兑换','我想取消'];const childReasonCodes=['CHANGED_MIND','WAIT_FOR_LATER','OTHER']
const titles:Record<string,string>={rewards:'把奖励约定好',rewardEdit:props.query.id?'编辑奖励':'添加一份奖励',reward:'奖励详情',order:'兑换订单',wishes:'一个小心愿',childReward:'我想要的奖励',orders:'我的兑换',childOrder:'这份小心愿'}
const {loading,error,busy,reload,act,session}=usePage(props.page,load,isChildPage?'child':'guardian')
const selectedChild=computed(()=>childId.value||session.view?.childId||'')
const activeOrder=computed(()=>order.value?.allowedActions.includes('CANCEL'))
const rewardIcon=(r?:Partial<Reward>|null)=>r?.artKey==='game'?'🎮':r?.artKey==='icecream'?'🍦':r?.artKey==='fries'?'🍟':r?.category==='EXPERIENCE'?'☀':r?.artKey==='book'?'▤':'◇'
async function load(){
 if(!isChildPage){children.value=await getAll<Child>(familyPath('/children'),{status:'ACTIVE'});if(!childId.value&&children.value.length===1)childId.value=children.value[0].id}
 if(props.page==='rewards'){await loadRewards();if(tab.value==='orders')await loadOrders();return}
 if(props.page==='wishes'){[account.value,wish.value]=await Promise.all([get<Account>(childPath(undefined,'/account')),get<Wish>(childPath(undefined,'/wish'))]);await Promise.all([loadRewards(),loadOrders()]);return}
 if(props.page==='orders'){await loadOrders();return}
 if(['order','childOrder'].includes(props.page)){order.value=await get<Order>(familyPath(`/orders/${props.query.id}`));account.value=await get<Account>(childPath(order.value.childId,'/account'));return}
 if(props.query.id){reward.value=await get<Reward>(familyPath(`/rewards/${props.query.id}`));if(props.page==='rewardEdit'){const r=reward.value;form.value={name:r.name,description:r.description||'',category:r.category,benefitDescription:r.benefitDescription,timeMinutes:String(r.timeMinutes||20),artKey:r.artKey||'gift',costPoints:String(r.costPoints),stockMode:r.stockMode,initialStock:String(r.stockAvailable||0),weeklyLimit:r.weeklyLimit?String(r.weeklyLimit):'',childIds:r.childIds||[]}}else if(selectedChild.value)await loadAvailability()}
}
async function loadRewards(more=false){const result=await get<PageResult<Reward>>(familyPath('/rewards'),{status:isChildPage?undefined:status.value||undefined,category:category.value||undefined,childId:isChildPage?session.view?.childId:childId.value||undefined,cursor:more?cursor.value:undefined});rewards.value=more?[...rewards.value,...result.items]:result.items;cursor.value=result.nextCursor||null;hasMore.value=result.hasMore}
async function loadOrders(more=false){const result=await get<PageResult<Order>>(isChildPage?childPath(undefined,'/orders'):familyPath('/orders'),{status:status.value||undefined,childId:!isChildPage?childId.value||undefined:undefined,cursor:more?orderCursor.value:undefined});orders.value=more?[...orders.value,...result.items]:result.items;orderCursor.value=result.nextCursor||null;ordersMore.value=result.hasMore}
async function loadAvailability(){if(!reward.value||!selectedChild.value)return;[availability.value,account.value]=await Promise.all([get<Availability>(childPath(selectedChild.value,`/reward-availability/${reward.value.id}`)),get<Account>(childPath(selectedChild.value,'/account'))])}
function toggleChild(id:string){form.value.childIds=form.value.childIds.includes(id)?form.value.childIds.filter(x=>x!==id):[...form.value.childIds,id]}
async function saveReward(publish=false){await act(async()=>{const f=form.value;if([...f.name.trim()].length<2||[...f.name.trim()].length>40)throw new Error('奖励名称需2—40字');if(!f.benefitDescription.trim()||[...f.benefitDescription.trim()].length>200)throw new Error('请用1—200字说清楚一份奖励是什么');if(!integer(f.costPoints,1,100000))throw new Error('奖励积分需为1—100,000的整数');if(f.category==='TIME'&&!integer(f.timeMinutes,1,1440))throw new Error('时间奖励需为1—1,440整分钟');if(f.weeklyLimit!==''&&!integer(f.weeklyLimit,1,100))throw new Error('每周次数需为1—100的整数，或留空表示不限');if(!f.childIds.length)throw new Error('至少选择一名适用孩子');if(f.stockMode==='FINITE'&&!integer(f.initialStock,0,1000000))throw new Error('初始库存需为0—1,000,000的整数');const body={name:f.name.trim(),description:f.description.trim(),category:f.category,benefitDescription:f.benefitDescription.trim(),...(f.category==='TIME'?{timeMinutes:Number(f.timeMinutes)}:{timeMinutes:null}),artKey:f.artKey,costPoints:Number(f.costPoints),stockMode:f.stockMode,weeklyLimit:f.weeklyLimit===''?null:Number(f.weeklyLimit),childIds:f.childIds,...(!reward.value?(f.stockMode==='FINITE'?{initialStock:Number(f.initialStock)}:{}):{expectedVersion:reward.value.version})};let saved=await mutate<Reward>(reward.value?'PATCH':'POST',reward.value?familyPath(`/rewards/${reward.value.id}`):familyPath('/rewards'),body,'保存奖励');if(publish)saved=await mutate<Reward>('POST',familyPath(`/rewards/${saved.id}/status`),{status:'ACTIVE',expectedVersion:saved.version},'上架奖励');go('reward',{id:saved.id},true)},publish?'奖励已上架':'奖励已保存')}
async function changeStatus(next:string){await act(async()=>{const accepted=await new Promise<boolean>(resolve=>uni.showModal({title:next==='ARCHIVED'?'归档奖励':'更新奖励状态',content:'这只影响新的兑换申请，已有订单仍按原约定批准、兑现或取消。',success:r=>resolve(r.confirm)}));if(!accepted)return;reward.value=await mutate<Reward>('POST',familyPath(`/rewards/${reward.value!.id}/status`),{status:next,expectedVersion:reward.value!.version},'更新奖励状态')})}
async function adjustStock(){await act(async()=>{if(!integer(stockDelta.value,-1000000,1000000)||Number(stockDelta.value)===0||!stockReason.value.trim())throw new Error('请输入非零整数库存变化和原因');await mutate('POST',familyPath(`/rewards/${reward.value!.id}/stock-adjustments`),{delta:Number(stockDelta.value),reason:stockReason.value.trim(),expectedStockVersion:reward.value!.stockVersion},'调整奖励库存');stockDelta.value='';stockReason.value='';await load()},'库存已更新')}
async function setWish(){await act(async()=>{if(!selectedChild.value)throw new Error('请先选择孩子');const current=await get<Wish>(childPath(selectedChild.value,'/wish'));await mutate('PUT',childPath(selectedChild.value,'/wish'),{rewardId:reward.value!.id,...(current.wish?{expectedVersion:current.wish.version}:{})},'设置当前心愿');uni.showToast({title:'已设为当前心愿，不预留积分',icon:'none'})})}
async function clearWish(){await act(async()=>{if(!wish.value?.wish)return;await mutate('DELETE',childPath(undefined,'/wish'),{expectedVersion:wish.value.wish.version},'清除心愿目标');wish.value=await get<Wish>(childPath(undefined,'/wish'))})}
async function beginRequest(){await act(async()=>{if(!selectedChild.value)throw new Error('请选择受益孩子');await loadAvailability();if(!availability.value?.canRequest)throw new Error((availability.value?.blockingReasons||[]).map(reasonLabel).join('；')||'暂时不能申请');confirmRequest.value=true})}
async function submitRequest(){await act(async()=>{if(!availability.value||!reward.value)return;const result=await mutate<{order:Order;account:Account}>('POST',childPath(selectedChild.value,'/orders'),{rewardId:reward.value.id,expectedRewardVersion:availability.value.rewardVersion,expectedCostPoints:availability.value.costPoints},'申请兑换奖励');confirmRequest.value=false;account.value=result.account;go(isChildPage?'childOrder':'order',{id:result.order.id},true)},'申请已提交，积分已预留')}
function reasonLabel(code:string){return ({ACCOUNT_FROZEN:'积分记录正在核对，请稍后联系家庭负责人处理',INSUFFICIENT_POINTS:'可用积分不足',OUT_OF_STOCK:'这份奖励暂时没有库存',WEEKLY_LIMIT_REACHED:'本周申请次数已用完',REWARD_UNAVAILABLE:'奖励暂未上架',NOT_APPLICABLE:'这份奖励没有安排给当前孩子'} as Record<string,string>)[code]||code}
function beginAction(next:string){action.value=next;reason.value='';note.value='';delivered.value=false}
async function orderAction(){await act(async()=>{const o=order.value!;if(['cancel','reject'].includes(action.value)&&!isChildPage&&!reason.value.trim())throw new Error('请填写原因');if(action.value==='fulfill'&&!delivered.value)throw new Error('请确认已经实际提供完整奖励');const body={expectedVersion:o.version,...(action.value==='approve'?{arrangementNote:note.value.trim()}:action.value==='fulfill'?{note:note.value.trim()}:isChildPage?{reasonCode:childReason.value}:{reason:reason.value.trim()})};await mutate('POST',familyPath(`/orders/${o.id}/${action.value}`),body,({approve:'批准兑换',reject:'拒绝兑换',cancel:'取消未兑现订单',fulfill:'确认已实际兑现'} as Record<string,string>)[action.value]);action.value='';await load()},'订单已更新')}
const filters=computed(()=>props.page==='orders'||tab.value==='orders'?['','PENDING_APPROVAL','READY','FULFILLED','CANCELED','REJECTED','EXPIRED']:['','ACTIVE','INACTIVE','DRAFT','ARCHIVED'])
</script>
<template><AppShell :title="titles[page]" :tab="page==='rewards'?'rewards':page==='wishes'?'wishes':''" :back="!['rewards','wishes'].includes(page)" :loading="loading" :error="error" @retry="reload">
<template v-if="page==='rewardEdit'&&!session.isFamilyReadOnly"><view class="field"><text class="field-label">奖励名称</text><input class="input" v-model="form.name" maxlength="40" placeholder="例如：游戏20分钟"/></view><view class="field"><text class="field-label">奖励类别</text><picker :range="categories.map(label)" :value="categories.indexOf(form.category)" @change="form.category=categories[Number($event.detail.value)]"><view class="select-control">{{label(form.category)}}</view></picker></view><view class="field"><text class="field-label">一份奖励是什么（必填）</text><textarea class="textarea" v-model="form.benefitDescription" maxlength="200" placeholder="说清楚数量、具体内容和如何安排"/></view><view v-if="form.category==='TIME'" class="field"><text class="field-label">一份包含多少整分钟</text><input class="input" type="number" v-model="form.timeMinutes"/><text class="caption">只是家庭约定，不自动控制设备，不拆分使用。</text></view><view class="field"><text class="field-label">更多说明（选填）</text><textarea class="textarea" v-model="form.description" maxlength="500"/></view><view class="field"><text class="field-label">兑换积分</text><input class="input" type="number" v-model="form.costPoints"/></view><view class="field"><text class="field-label">内置插画</text><picker :range="artNames" :value="Math.max(0,artKeys.indexOf(form.artKey))" @change="form.artKey=artKeys[Number($event.detail.value)]"><view class="select-control">{{artNames[Math.max(0,artKeys.indexOf(form.artKey))]}}</view></picker></view><text class="field-label section">适用孩子</text><view class="chip-row"><button v-for="c in children" :key="c.id" class="chip" :class="{active:form.childIds.includes(c.id)}" @tap="toggleChild(c.id)">{{c.nickname}}</button></view><view class="field"><text class="field-label">库存方式</text><view class="tabs"><button :disabled="!!reward&&reward.status!=='DRAFT'" :class="[{active:form.stockMode==='UNLIMITED'}, {'is-disabled':(!!reward&&reward.status!=='DRAFT')}]" @tap="form.stockMode='UNLIMITED'">不限量</button><button :disabled="!!reward&&reward.status!=='DRAFT'" :class="[{active:form.stockMode==='FINITE'}, {'is-disabled':(!!reward&&reward.status!=='DRAFT')}]" @tap="form.stockMode='FINITE'">有限库存</button></view><text class="caption">发布后库存方式冻结；已有奖励的数量请从详情独立调整。</text></view><view v-if="form.stockMode==='FINITE'&&!reward" class="field"><text class="field-label">初始库存（份）</text><input class="input" v-model="form.initialStock" type="number"/></view><view class="field"><text class="field-label">每个孩子每自然周最多几次</text><input class="input" v-model="form.weeklyLimit" type="number" placeholder="留空表示不限，填写1—100"/><text class="caption">周一00:00起，已有订单始终按原申请周占用次数。</text></view><view class="notice">以后修改价格和说明，只影响新申请，已经申请的订单保持原约定。</view><view class="button-stack"><button :class="{'is-disabled':(busy)}" class="primary" :loading="busy" :disabled="busy" @tap="saveReward(true)">保存并上架</button><button :class="{'is-disabled':(busy)}" class="secondary" :disabled="busy" @tap="saveReward(false)">保存{{reward?'修改':'草稿'}}</button></view></template>
<template v-else-if="['rewards','wishes','orders'].includes(page)">
<template v-if="page==='wishes'"><PointBalance :account="account"/><view v-if="wish?.rewardSummary" class="hero"><text class="eyebrow">我的当前心愿</text><view class="row"><view class="art sun">{{rewardIcon(wish.rewardSummary)}}</view><view class="grow"><text class="card-title">{{wish.rewardSummary.name}}</text><text class="caption">{{wish.rewardSummary.status==='ACTIVE'?`还差${wish.pointsGap}积分`:'暂时不能兑换，可以换个目标'}}</text></view></view><view class="meter"><view class="meter-fill" :style="{width:Math.min(100,Math.max(0,wish.progress<=1?wish.progress*100:wish.progress))+'%'}"/></view><view class="row between"><text class="points">{{account?.availablePoints??'—'}} / {{wish.rewardSummary.costPoints}} 积分</text><button class="text-button" @tap="go('childReward',{id:wish.rewardSummary.id})">去看看 →</button></view><button class="text-button small" @tap="clearWish">换个心愿目标</button></view><view v-else class="notice">选一个想努力换到的奖励。设为心愿不会预留积分或库存。</view><view class="section-head"><text class="section-title">我的兑换</text><button class="text-button" @tap="go('orders')">全部兑换 →</button></view><view v-for="o in orders.slice(0,3)" :key="o.id" class="card" @tap="go('childOrder',{id:o.id})"><view class="row between"><text class="card-title">{{o.rewardSnapshot.name}}</text><StatusPill :status="o.status"/></view><text class="caption">{{o.costPointsSnapshot}}积分 · 一份</text></view><view v-if="!orders.length" class="card muted">申请后，在这里看家长的回应。</view><text class="section-title section">奖励小屋</text></template>
<view v-if="page==='rewards'" class="section-head"><view class="tabs grow"><button :class="{active:tab==='catalog'}" @tap="tab='catalog';status='';act(()=>loadRewards())">奖励库</button><button :class="{active:tab==='orders'}" @tap="tab='orders';status='';act(()=>loadOrders())">兑换订单</button></view><button v-if="session.family?.family.status!=='ARCHIVED'" class="text-button" @tap="go('rewardEdit')">＋ 添加</button></view>
<view v-if="page!=='wishes'" class="chip-row"><button v-for="s in filters" :key="s||'all'" class="chip" :class="{active:status===s}" @tap="status=s;act(()=>page==='orders'||tab==='orders'?loadOrders():loadRewards())">{{s?label(s):'全部'}}</button></view>
<view v-if="!isChildPage&&children.length" class="field"><picker :range="['全部孩子',...children.map(c=>c.nickname)]" :value="children.findIndex(c=>c.id===childId)+1" @change="childId=children[Number($event.detail.value)-1]?.id||'';act(()=>tab==='orders'?loadOrders():loadRewards())"><view class="select-control">{{children.find(c=>c.id===childId)?.nickname||'全部孩子'}}</view></picker></view>
<template v-if="page==='orders'||page==='rewards'&&tab==='orders'"><view v-for="o in orders" :key="o.id" class="card" @tap="go(isChildPage?'childOrder':'order',{id:o.id})"><view class="row"><view class="art sun">{{rewardIcon(o.rewardSnapshot)}}</view><view class="grow"><text class="card-title">{{o.rewardSnapshot.name}}</text><text class="caption">{{o.child?.nickname||o.childNickname||'孩子兑换'}} · {{o.costPointsSnapshot}}积分</text><StatusPill :status="o.status"/></view></view><text class="caption section">申请于 {{dateTime(o.createdAt)}}</text></view><EmptyState v-if="!orders.length&&!loading" title="这里还没有兑换" description="申请奖励后，可以在这里查看进展。"/><LoadMore :has-more="ordersMore" :loading="busy" @more="act(()=>loadOrders(true))"/></template>
<template v-else><view class="chip-row"><button class="chip" :class="{active:!category}" @tap="category='';act(()=>loadRewards())">全部奖励</button><button v-for="c in categories" :key="c" class="chip" :class="{active:category===c}" @tap="category=c;act(()=>loadRewards())">{{label(c)}}</button></view><view class="reward-grid"><view v-for="r in rewards" :key="r.id" class="reward-card" @tap="go(isChildPage?'childReward':'reward',{id:r.id})"><view class="art sun">{{rewardIcon(r)}}</view><text class="card-title">{{r.name}}</text><text class="points">{{r.costPoints}} 积分</text><text class="caption">{{r.stockMode==='UNLIMITED'?'不限量':`余${r.stockAvailable??0}份`}}</text><StatusPill v-if="!isChildPage" :status="r.status"/></view></view><EmptyState v-if="!rewards.length&&!loading" title="还没有这类奖励" :description="isChildPage?'和家长一起商量一份想要的奖励吧。':'先添加一份具体、可以兑现的奖励。'"/><LoadMore :has-more="hasMore" :loading="busy" @more="act(()=>loadRewards(true))"/></template></template>
<template v-else-if="['reward','childReward'].includes(page)&&reward"><view class="hero"><view class="art sun">{{rewardIcon(reward)}}</view><text class="page-title section">{{reward.name}}</text><text class="points section">{{reward.costPoints}} 积分 · 一份</text><StatusPill v-if="!isChildPage" :status="reward.status"/></view><view class="card"><text class="card-title">这份奖励是什么</text><text class="body-copy">{{reward.benefitDescription}}</text><text v-if="reward.description" class="muted body-copy">{{reward.description}}</text><text v-if="reward.category==='TIME'" class="caption section">一次提供{{reward.timeMinutes}}整分钟，小程序不控制设备、不自动计时、不拆分使用。</text></view><view v-if="!isChildPage" class="field"><text class="field-label">为哪个孩子申请</text><picker :range="children.map(c=>c.nickname)" @change="childId=children[Number($event.detail.value)]?.id;act(loadAvailability)"><view class="select-control">{{children.find(c=>c.id===childId)?.nickname||'请选择孩子'}}</view></picker></view><PointBalance v-if="account" :account="account"/><view class="card summary"><view class="summary-row"><text class="summary-label">库存</text><text class="summary-value">{{reward.stockMode==='UNLIMITED'?'不限量':`当前可用${availability?.stockAvailable??reward.stockAvailable??0}份`}}</text></view><view class="summary-row"><text class="summary-label">每自然周</text><text class="summary-value">{{reward.weeklyLimit?`每人最多${reward.weeklyLimit}次`:'不限次数'}}</text></view><view v-if="availability?.weeklyRemaining!=null" class="summary-row"><text class="summary-label">本人本周可申请</text><text class="summary-value">{{availability.weeklyRemaining}}次</text></view></view><view v-if="availability&&!availability.canRequest" class="notice warning">{{availability.blockingReasons.map(reasonLabel).join('；')}}</view><view v-if="!session.isFamilyReadOnly" class="button-stack"><button :class="{'is-disabled':(busy||!selectedChild||!!availability&&!availability.canRequest)}" class="primary" :disabled="busy||!selectedChild||!!availability&&!availability.canRequest" @tap="beginRequest">{{isChildPage?'申请这份奖励':'为这个孩子申请'}}</button><button :class="{'is-disabled':(busy)}" v-if="selectedChild" class="secondary" :disabled="busy" @tap="setWish">设为当前心愿</button></view><view v-if="confirmRequest&&availability&&account" class="card section"><text class="section-title">确认这份约定</text><text class="body-copy">{{reward.name}} · 一份 · {{availability.costPoints}}积分</text><view class="summary section"><view class="summary-row"><text class="summary-label">申请后可用</text><text class="summary-value">{{account.availablePoints-availability.costPoints}}积分</text></view><view class="summary-row"><text class="summary-label">申请后预留</text><text class="summary-value">{{account.heldPoints+availability.costPoints}}积分</text></view></view><view class="notice section">家长批准时才花掉。72小时内未批准，会释放预留。即使家长代申请，也需批准。</view><button :class="{'is-disabled':(busy)}" class="primary full" :loading="busy" :disabled="busy" @tap="submitRequest">预留{{availability.costPoints}}积分并申请</button><button class="text-button full" @tap="confirmRequest=false">返回再想想</button></view><template v-if="!session.isFamilyReadOnly&&!isChildPage&&reward.status!=='ARCHIVED'"><view class="divider section"/><text class="section-title">管理奖励</text><view class="button-stack"><button class="secondary" @tap="go('rewardEdit',{id:reward.id})">编辑奖励</button><button class="secondary" @tap="changeStatus(reward.status==='ACTIVE'?'INACTIVE':'ACTIVE')">{{reward.status==='ACTIVE'?'下架，暂停新申请':'上架奖励'}}</button><button class="danger-button" @tap="changeStatus('ARCHIVED')">归档奖励</button></view><view v-if="reward.stockMode==='FINITE'" class="card section"><text class="card-title">独立调整库存</text><view class="field"><text class="field-label">增加或减少数量</text><input class="input" v-model="stockDelta" type="text" placeholder="如3或-1，不能为0"/></view><view class="field"><text class="field-label">原因</text><input class="input" v-model="stockReason" maxlength="200"/></view><button :class="{'is-disabled':(busy)}" class="secondary full" :disabled="busy" @tap="adjustStock">确认调整库存</button></view></template></template>
<template v-else-if="['order','childOrder'].includes(page)&&order"><StatusPill :status="order.status"/><text class="page-title section">{{order.rewardSnapshot.name}}</text><text class="caption section">{{order.child?.nickname||order.childNickname||'本人的兑换'}} · 一份奖励 · 原价{{order.costPointsSnapshot}}积分</text><view class="notice section">{{order.status==='PENDING_APPROVAL'?`已预留${order.costPointsSnapshot}积分，尚未花掉。`:order.status==='READY'?'家长同意啦，一起安排什么时候兑现吧。':order.status==='FULFILLED'?'这份奖励已实际提供，不能取消或退款。':'本订单已结束，释放或退款请以最新账本为准。'}}</view><text class="body-copy">{{order.rewardSnapshot.benefitDescription}}</text><PointBalance class="section" :account="account"/><view class="timeline section"><view class="timeline-item"><text class="timeline-title">申请奖励</text><text class="caption">{{dateTime(order.createdAt)}} · 原申请周 {{order.requestWeekStart}}</text><text v-if="order.status==='PENDING_APPROVAL'" class="caption">批准截止 {{dateTime(order.approvalExpiresAt)}}</text></view><view v-if="order.approvedAt" class="timeline-item"><text class="timeline-title">家长已批准</text><text class="caption">{{dateTime(order.approvedAt)}}</text><text v-if="order.arrangementNote" class="body-copy">{{order.arrangementNote}}</text></view><view v-if="order.fulfilledAt" class="timeline-item"><text class="timeline-title">已经实际兑现</text><text class="caption">{{dateTime(order.fulfilledAt)}}</text><text v-if="order.fulfillmentNote" class="body-copy">{{order.fulfillmentNote}}</text></view><view v-if="order.canceledAt||order.decisionReason" class="timeline-item"><text class="timeline-title">{{label(order.status)}}</text><text class="caption">{{dateTime(order.canceledAt)}}</text><text class="body-copy">{{order.decisionReason}}</text></view></view><view class="button-stack"><template v-if="!isChildPage&&order.allowedActions.includes('APPROVE')"><button class="primary" @tap="beginAction('approve')">批准并花费{{order.costPointsSnapshot}}积分</button><button class="secondary" @tap="beginAction('reject')">暂不同意，说明原因</button></template><button v-if="!isChildPage&&order.allowedActions.includes('FULFILL')" class="primary" @tap="beginAction('fulfill')">已经实际兑现</button><button v-if="activeOrder" class="secondary" @tap="beginAction('cancel')">{{order.status==='READY'?`取消并退回${order.costPointsSnapshot}积分`:'取消这次申请'}}</button></view><view v-if="action" class="card section"><text class="section-title">{{action==='approve'?'批准这份奖励':action==='fulfill'?'确认已经实际兑现':action==='reject'?'暂不同意这次申请':'取消这次兑换'}}</text><view class="notice warning section">{{action==='approve'?'批准后积分正式花掉，家长需要安排兑现这份承诺。':action==='fulfill'?'实际提供完整奖励后再确认，确认后不能取消或退款。':`将按原价返还${order.costPointsSnapshot}积分，同时恢复有限库存和原申请周次数。`}}</view><view v-if="action==='fulfill'" class="check-row" @tap="delivered=!delivered"><checkbox :checked="delivered" color="#176b5b"/><text>已经给了孩子约定的完整奖励</text></view><view v-if="['approve','fulfill'].includes(action)" class="field"><text class="field-label">{{action==='approve'?'安排说明':'兑现说明'}}（选填）</text><textarea class="textarea" v-model="note" maxlength="200"/></view><view v-else-if="isChildPage" class="field"><text class="field-label">取消原因</text><picker :range="childReasons" :value="childReasonCodes.indexOf(childReason)" @change="childReason=childReasonCodes[Number($event.detail.value)]"><view class="select-control">{{childReasons[childReasonCodes.indexOf(childReason)]}}</view></picker></view><view v-else class="field"><text class="field-label">原因（必填）</text><textarea class="textarea" v-model="reason" maxlength="200"/></view><button :class="{'is-disabled':(busy)}" class="primary full" :loading="busy" :disabled="busy" @tap="orderAction">确认{{action==='approve'?'批准':action==='fulfill'?'已兑现':action==='reject'?'未批准':'取消'}}</button><button class="text-button full" @tap="action=''">返回</button></view></template>
</AppShell></template>
